```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Enrichment fetch, as requested by the graph author. The result does not
        // influence the output; transport failures are ignored.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&published.date)
        );
        let _ = crate::aap::caps::http_client::fetch(&url);

        let mut recorded: u32 = 0;
        if published.published {
            for id in &published.considered {
                crate::aap::caps::state_rw::put(id, &published.date);
                recorded += 1;
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

I used the digest's `date` as the `q` value, since `PublishedDigest` has no text field. Ids are marked seen only when `published` is true, so `recorded` is 0 otherwise. The enrichment result is ignored, so the output is unchanged.

